// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }

    function testFuzz_property(address actor) public {
        // Wide admissible domain: any address may attempt the privileged entry point.
        vm.assume(actor != address(0));

        address ownerBefore = c.owner();
        bool ok;
        vm.prank(actor);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: owned() succeeds iff the caller was the owner beforehand,
        // and a successful call leaves the owner equal to the caller (reassertion).
        assertTrue(
            (ok == (actor == ownerBefore)) && (!ok || c.owner() == actor),
            "owned() gated by owner and reasserts owner = msg.sender"
        );
    }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test() public {
    c.owned();
    assert(c.owner() == msg.sender);
  }
  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test() public {
    c.owned();
    assert(c.owner() == address(this));
  }
  receive() external payable {}
  fallback() external {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test() public {
    require(c.owner() != address(this));
    bool ok;
    (ok, ) = address(c).call(abi.encodeWithSelector(c.owned.selector));
    assert(!ok);
  }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function testNonOwnerCannotMint(uint256 amount) public {
        require(c.owner() != address(this));
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.mintToken.selector, address(this), amount)
        );
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function testBurnReducesSupply(uint256 amt) public {
    require(c.owner() == address(this));
    c.mintToken(address(this), amt);
    uint256 supplyBefore = c.totalSupply();
    c.burn(amt);
    assert(c.totalSupply() == supplyBefore - amt);
  }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test(uint256 v) public {
    require(v > 0 && v <= c.totalSupply() && v <= c.balanceOf(address(this)));
    uint256 s0 = c.totalSupply();
    c.burn(v);
    assert(c.totalSupply() == s0 - v);
  }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function burnCheck(uint256 _v) public {
    require(_v > 1);
    address ownerAddr = c.owner();
    require(c.balanceOf(ownerAddr) >= _v);
    c.burn(_v);
    assert(c.totalSupply() == c.balanceOf(ownerAddr));
  }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function test() public {
    // burn the caller's entire balance; caller is owner with full initial supply
    uint256 bal = c.balanceOf(address(this));
    bool ok;
    // state-changing call must be top-level; use try-free approach via separate call
    c.burn(bal);
    ok = true;
    assert(c.totalSupply() == 0 && c.balanceOf(address(this)) == 0 && ok);
  }

  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test(uint256 amount) public {
    require(c.owner() == address(this));
    require(c.balanceOf(address(this)) >= amount);
    uint256 balBefore = c.balanceOf(address(this));
    c.burn(amount);
    assert(c.balanceOf(address(this)) == balBefore - amount);
  }
  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test(uint256 v) public {
    uint256 bal0 = c.balanceOf(address(this));
    require(bal0 >= v);
    c.burn(v);
    assert(c.balanceOf(address(this)) == bal0 - v);
  }
  receive() external payable {}
  fallback() external payable {}
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function test(uint256 amt) public {
    address o = c.owner();
    require(o != address(this));
    c.mintToken(address(this), amt);
    uint256 ob = c.balanceOf(o);
    c.burn(amt);
    assert(c.balanceOf(o) == ob);
  }

  receive() external payable {}
  fallback() external payable {}
}
